impl Solution {
    pub fn palindrome_path(n:i32,edges:Vec<Vec<i32>>,s:String,queries:Vec<String>)->Vec<bool>{
        let n=n as usize;let mut g=vec![Vec::<usize>::new();n];for e in edges{let u=e[0] as usize;let v=e[1] as usize;g[u].push(v);g[v].push(u);}let mut log=1usize;while(1usize<<log)<=n{log+=1;}let mut up=vec![vec![0usize;n];log];let mut depth=vec![0usize;n];let mut tin=vec![0usize;n];let mut tout=vec![0usize;n];let mut timer=0usize;let mut st=vec![(0usize,0usize,false)];while let Some((u,p,exit))=st.pop(){if !exit{tin[u]=timer;timer+=1;up[0][u]=p;for j in 1..log{up[j][u]=up[j-1][up[j-1][u]];}st.push((u,p,true));for &v in g[u].iter().rev(){if v==p{continue;}depth[v]=depth[u]+1;st.push((v,u,false));}}else{tout[u]=timer-1;}}
        fn lca(mut a:usize,mut b:usize,depth:&[usize],up:&[Vec<usize>])->usize{if depth[a]<depth[b]{std::mem::swap(&mut a,&mut b);}let diff=depth[a]-depth[b];for j in 0..up.len(){if diff&(1usize<<j)!=0{a=up[j][a];}}if a==b{return a;}for j in (0..up.len()).rev(){if up[j][a]!=up[j][b]{a=up[j][a];b=up[j][b];}}up[0][a]}
        struct Seg{tree:Vec<i32>,lazy:Vec<i32>}impl Seg{fn new(base:&[i32])->Self{let n=base.len();let mut s=Seg{tree:vec![0;4*n+5],lazy:vec![0;4*n+5]};s.build(1,0,n-1,base);s}fn build(&mut self,node:usize,l:usize,r:usize,b:&[i32]){if l==r{self.tree[node]=b[l];return;}let m=(l+r)/2;self.build(node*2,l,m,b);self.build(node*2+1,m+1,r,b);}fn apply(&mut self,node:usize,v:i32){self.tree[node]^=v;self.lazy[node]^=v;}fn push(&mut self,node:usize){let v=self.lazy[node];if v!=0{self.apply(node*2,v);self.apply(node*2+1,v);self.lazy[node]=0;}}fn update(&mut self,node:usize,l:usize,r:usize,ql:usize,qr:usize,v:i32){if qr<l||r<ql{return;}if ql<=l&&r<=qr{self.apply(node,v);return;}self.push(node);let m=(l+r)/2;self.update(node*2,l,m,ql,qr,v);self.update(node*2+1,m+1,r,ql,qr,v);}fn point(&mut self,node:usize,l:usize,r:usize,idx:usize)->i32{if l==r{return self.tree[node];}self.push(node);let m=(l+r)/2;if idx<=m{self.point(node*2,l,m,idx)}else{self.point(node*2+1,m+1,r,idx)}}}
        let bytes=s.as_bytes();let mut label=vec![0i32;n];for i in 0..n{label[i]=1i32<<(bytes[i]-b'a');}let mut order=vec![0usize;n];for i in 0..n{order[tin[i]]=i;}let mut rx=vec![0i32;n];for pos in 0..n{let u=order[pos];rx[u]=if u==0{label[u]}else{rx[up[0][u]]^label[u]};}let mut base=vec![0i32;n];for i in 0..n{base[tin[i]]=rx[i];}let mut seg=Seg::new(&base);let mut ans=Vec::new();for q in queries{let p:Vec<&str>=q.split_whitespace().collect();let u:usize=p[1].parse().unwrap();if p[0]=="update"{let nm=1i32<<(p[2].as_bytes()[0]-b'a');let d=label[u]^nm;if d!=0{seg.update(1,0,n-1,tin[u],tout[u],d);label[u]=nm;}}else{let v:usize=p[2].parse().unwrap();let w=lca(u,v,&depth,&up);let mask=seg.point(1,0,n-1,tin[u])^seg.point(1,0,n-1,tin[v])^label[w];ans.push(mask==0||(mask&(mask-1))==0);}}ans
    }
}
